class FieldOracleTests(unittest.TestCase):
    def test_ordered_duplicate_occurrences_survive_repeated_sections_comments_and_crlf(self):
        raw = (b"\xef\xbb\xbf# retained header\r\n[physics]\r\n Ag = 9.813000 # first\r\nAg=9.81\r\n"
               b"[unknown]\r\nMystery=1.234567890123456789\r\n[PHYSICS] # repeated block\r\nAG = 9.8 # third\r\n")
        entries = [item for item in occurrences(raw) if item["address"] == "physics/ag"]
        self.assertEqual([item["occurrence"] for item in entries], [1, 2, 3])
        self.assertEqual([item["section_occurrence"] for item in entries], [1, 1, 2])
        self.assertEqual([item["line"] for item in entries], [3, 4, 8])
        self.assertEqual([item["value"] for item in entries], ["9.813000", "9.81", "9.8"])
        changed = expected_edit(raw, "PHYSICS/AG", "9.7", 2)
        self.assertEqual(changed, raw.replace(b"Ag=9.81\r\n", b"Ag=9.7\r\n"))
        self.assertTrue(assert_exact_edit(raw, changed, "physics/ag", "9.7", 2)["only_target_value_span_changed"])

    def test_duplicate_or_missing_selection_never_silently_chooses_first(self):
        raw = b"[physics]\nAg=9.8\nAg=9.7\n"
        for address, occurrence in (("physics/ag", None), ("physics/ag", 3), ("physics/vicouv", None)):
            with self.subTest(address=address, occurrence=occurrence), self.assertRaises(ValueError):
                selected(raw, address, occurrence)

    def test_byte_oracle_rejects_collateral_reformatting_even_when_numeric_value_is_correct(self):
        before = b"[physics]\r\n  Ag  =  9.813000   # keep\r\n[custom]\r\nx=1e-19\r\n"
        correct = expected_edit(before, "physics/ag", "9.8")
        for changed in (correct.replace(b"\r\n", b"\n"), correct.replace(b"  Ag  =  ", b"Ag="),
                        correct.replace(b"1e-19", b"0.0000000000000000001"), correct.replace(b"# keep", b"# changed")):
            with self.subTest(changed=changed), self.assertRaises(AssertionError):
                assert_exact_edit(before, changed, "physics/ag", "9.8")

    def test_noop_expected_edit_preserves_entire_file(self):
        before = b"[physics]\nAg=9.813\n"
        self.assertEqual(expected_edit(before, "physics/ag", "9.813"), before)

    def test_unrelated_graph_hashes_and_file_set_are_immutable(self):
        before = {"f34.mdu": "old", "f34_net.nc": "mesh", "f34_001.bc": "forcing"}
        after = before | {"f34.mdu": "new"}
        self.assertEqual(assert_unrelated_files(before, after, "f34.mdu")["unrelated_unchanged"], 2)
        for bad in (after | {"f34_001.bc": "changed"}, after | {"extra": "added"}, {"f34.mdu": "new"}):
            with self.assertRaises(AssertionError):
                assert_unrelated_files(before, bad, "f34.mdu")

    def test_source_literals_preserve_duplicate_read_and_write_occurrences(self):
        source = """! call prop_get(p, 'physics', 'fake', ignored)
call prop_get(md_ptr, 'physics', 'Ag', ag) ! actual reader
call prop_set(prop_ptr, &
    & 'physics', 'Ag', ag, 'Gravitational ! acceleration')
call prop_set(prop_ptr, 'geometry', 'StructureFile', a)
call prop_set(prop_ptr, 'geometry', 'StructureFile', b)
call prop_get(md_ptr, dynamic_section, dynamic_key, anything)
"""
        rows = fortran_literals(source)
        self.assertEqual([(row["operation"], row["address"], row["line"]) for row in rows],
                         [("get", "physics/ag", 2), ("set", "physics/ag", 3),
                          ("set", "geometry/structurefile", 5), ("set", "geometry/structurefile", 6)])
        self.assertIn("Gravitational ! acceleration", rows[1]["statement"])

    def test_helper_alias_source_uses_annotations_without_importing_or_conflating_comment_class(self):
        source = """raise RuntimeError('must never execute helper source')
class Physics:
    class Comments:
        ag: str = Field('description', alias='Ag')
    ag: float = Field(9.81, alias='Ag')
    uniffrictcoef: float = Field(.023, alias='unifFrictCoef')
class Output:
    hisinterval: list[float] = Field([300.], alias='hisInterval')
"""
        rows = helper_aliases(source)
        self.assertEqual([(row["class"], row["attribute"], row["alias"]) for row in rows],
                         [("Physics", "ag", "Ag"), ("Physics", "uniffrictcoef", "unifFrictCoef"),
                          ("Output", "hisinterval", "hisInterval")])

    def test_controlled_physics_cases_keep_friction_type_and_unit_explicit(self):
        self.assertEqual(CONTROLLED_FIELDS["physics/uniffrictcoef"]["requires"], {"physics/uniffricttype": "0"})
        self.assertEqual(CONTROLLED_FIELDS["physics/ag"]["before"], "9.813")
        self.assertNotIn("physics/salinity", CONTROLLED_FIELDS)

    def test_source_symbol_expression_excludes_call_parenthesis_preserves_helper_parentheses(self):
        self.assertEqual(first_argument("ag"), "ag")
        self.assertEqual(first_argument("trim(md_structurefile), 'Structures'"), "trim(md_structurefile)")
        self.assertEqual(first_argument("array(1,2), 3, success"), "array(1,2)")


@unittest.skipIf(nc is None, "netCDF4 optional run extra required")
class FieldDifferentialTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="dfm-e014-differential-")
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        self.left, self.right = self.root / "baseline.nc", self.root / "changed.nc"
        for path in (self.left, self.right):
            with nc.Dataset(path, "w") as ds:
                ds.createDimension("time", 3)
                ds.createDimension("station", 2)
                time = ds.createVariable("time", "f8", ("time",))
                time.units = "minutes since 1990-08-05 00:00:00 +00:00"
                time[:] = [0, 1, 2]
                x = ds.createVariable("station_x_coordinate", "f8", ("station",))
                x.standard_name, x.units = "projection_x_coordinate", "m"
                x[:] = [100, 200]
                field = ds.createVariable("waterlevel", "f8", ("time", "station"), fill_value=-999.)
                field.units = "m"
                values = np.ma.array([[1, 2], [3, 4], [5, 6]], mask=False)
                values.mask[1, 0] = True
                field[:] = values

    def test_actual_differentials_preserve_masks_and_use_changed_minus_baseline(self):
        with nc.Dataset(self.right, "r+") as ds:
            ds.variables["waterlevel"][2, 1] = 8
        result = netcdf_differential(self.left, self.right)
        self.assertEqual(result["changed_variables"], ["waterlevel"])
        value = next(v for v in result["variables"] if v["name"] == "waterlevel")
        self.assertEqual(value["max_abs_difference"], 2)
        self.assertEqual(value["paired_samples"], 5)
        self.assertEqual(value["baseline_masked"], 1)
        self.assertAlmostEqual(value["mean_difference"], .4)

    def test_equal_output_is_reported_equal_not_assumed_to_prove_edit_failed(self):
        self.assertTrue(netcdf_differential(self.left, self.right)["all_values_equal"])

    def test_coordinate_or_time_changes_are_not_hidden_by_plausible_physics_differences(self):
        with nc.Dataset(self.right, "r+") as ds:
            ds.variables["station_x_coordinate"][0] += 1
        with self.assertRaisesRegex(AssertionError, "static geometry"):
            netcdf_differential(self.left, self.right)


@unittest.skipIf(nc is None, "netCDF4 optional run extra required")
class EffectiveNativeFieldOracleTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="dfm-e014-effective-")
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        self.paths = [self.root / name for name in ("map.nc", "history.nc", "restart.nc")]
        for index, path in enumerate(self.paths):
            with nc.Dataset(path, "w") as ds:
                ds.createDimension("time", 1 if index == 2 else 3)
                ds.createDimension("faces", 48)
                ds.createDimension("links", 88)
                time = ds.createVariable("time", "f8", ("time",))
                time.units = "seconds since 2001-01-01 00:00:00"
                time[:] = [120] if index == 2 else [0, 60, 120]
                step = ds.createVariable("timestep", "f8", ("time",), fill_value=-999.)
                step.units = "seconds"
                step[:] = [1] if index == 2 else [.1, 1, 1]
                if index == 0:
                    for name, value in (("mesh2d_s1", .25), ("mesh2d_waterdepth", 3.25)):
                        var = ds.createVariable(name, "f8", ("time", "faces"), fill_value=-999.)
                        var.units = "m"
                        var[:] = value
                    for name, value in (("mesh2d_cfu", .041), ("mesh2d_cfutyp", 1)):
                        var = ds.createVariable(name, "f8", ("time", "links"), fill_value=-999.)
                        var.units = "-"
                        var[:] = value

    def read(self):
        return effective_fields(*self.paths, level=.25, manning=.041, dtmax=1.)

    def test_actual_level_depth_law_roughness_and_latest_timestep_are_verified(self):
        result = self.read()
        self.assertEqual(result["wet_faces"], 48)
        self.assertEqual(result["manning_links_per_first_output"], 88)
        self.assertEqual(result["effective_timesteps"]["history"]["values_seconds"], [.1, 1., 1.])

    def test_wrong_level_and_masked_initial_face_are_refused(self):
        with nc.Dataset(self.paths[0], "r+") as ds:
            ds["mesh2d_s1"][0, 20] = .0
        with self.assertRaises(AssertionError):
            self.read()
        with nc.Dataset(self.paths[0], "r+") as ds:
            ds["mesh2d_s1"][0, 20] = -999
        with self.assertRaisesRegex(AssertionError, "mask/location"):
            self.read()

    def test_wrong_law_or_changed_coefficient_is_not_hidden_by_correct_water_level(self):
        with nc.Dataset(self.paths[0], "r+") as ds:
            ds["mesh2d_cfutyp"][:] = 0
        with self.assertRaisesRegex(AssertionError, "Manning link"):
            self.read()
        with nc.Dataset(self.paths[0], "r+") as ds:
            ds["mesh2d_cfutyp"][:] = 1
            ds["mesh2d_cfu"][2, 44] = .023
        with self.assertRaises(AssertionError):
            self.read()

    def test_output_cadence_cannot_substitute_for_actual_effective_dtmax(self):
        with nc.Dataset(self.paths[1], "r+") as ds:
            ds["timestep"][:] = [.1, 60, 60]
        with self.assertRaisesRegex(AssertionError, "exceeded"):
            self.read()
        with nc.Dataset(self.paths[1], "r+") as ds:
            ds["timestep"][:] = [.1, .1, .1]
        with self.assertRaisesRegex(AssertionError, "No retained timestep reached"):
            self.read()

    def test_final_restart_timestep_is_checked_independently_of_map_and_history(self):
        with nc.Dataset(self.paths[2], "r+") as ds:
            ds["timestep"][:] = 2
        with self.assertRaisesRegex(AssertionError, "exceeded"):
            self.read()


class RegistryOracleTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="dfm-e014-registry-")
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        engine = self.root / "research/upstream/Delft3D" / ENGINE_SOURCE
        helper = self.root / "research/upstream/HYDROLIB-core" / HELPER_SOURCE
        engine.parent.mkdir(parents=True)
        helper.parent.mkdir(parents=True)
        engine.write_text("call prop_get(p, 'physics', 'Ag', ag)\ncall prop_set(p, 'physics', 'Ag', ag, 'Gravity')\n")
        helper.write_text("class Physics:\n    ag: float = Field(9.81, alias='ag')\n")
        self.registry = self.root / "registry.json"
        self.data = {"schema_version": 1, "installed_engine_source_revision": "unknown", "sources": {
            "engine": {"commit": PINNED_ENGINE, "path": ENGINE_SOURCE, "sha256": hashlib.sha256(engine.read_bytes()).hexdigest()},
            "hydrolib": {"path": HELPER_SOURCE, "sha256": hashlib.sha256(helper.read_bytes()).hexdigest()}},
            "records": {"physics/ag": {"engine": {"read": [1], "write": [2], "symbols": ["ag"]},
                                      "hydrolib": {"class": "Physics", "attribute": "ag", "alias": "ag", "line": 2, "type": "float"}}}}

    def audit(self):
        self.registry.write_text(json.dumps(self.data))
        return registry_oracle(self.registry, self.root)

    def test_real_source_anchors_alias_and_symbol_expression_must_all_match(self):
        self.assertEqual(self.audit()["state"], "passed")
        self.data["records"]["physics/ag"]["engine"]["symbols"] = ["ag)", "ag"]
        result = self.audit()
        self.assertEqual(result["state"], "metadata_mismatch")
        self.assertEqual(len(result["symbol_expression_issues"]), 1)

    def test_correct_source_file_hash_cannot_hide_incorrect_line_or_helper_alias(self):
        self.data["records"]["physics/ag"]["engine"]["read"] = [2]
        self.data["records"]["physics/ag"]["hydrolib"]["alias"] = "Gravity"
        result = self.audit()
        self.assertEqual(len(result["line_and_alias_issues"]), 2)

    def test_static_source_registry_must_not_infer_installed_suite_commit(self):
        self.data["installed_engine_source_revision"] = PINNED_ENGINE
        with self.assertRaisesRegex(AssertionError, "installed engine source"):
            self.audit()


@unittest.skipIf(nc is None, "netCDF4 optional run extra required")
class PublicFieldCliTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="dfm-e014-public-")
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name) / "channel"
        self.mdu = portable_channel(self.root)
        # E014's native case established BedlevType=3, not an arbitrary mode
        # selected implicitly from the mere existence of valid node elevations.
        self.mdu.write_bytes(self.mdu.read_bytes().replace(b"Kmx=0\r\n", b"Kmx=0\r\nBedlevType=3\r\n"))

    def cli(self, *args, expected=0):
        from dfm_cli.cli import main
        output = io.StringIO()
        with contextlib.redirect_stdout(output):
            code = main([str(arg) for arg in args])
        payload = json.loads(output.getvalue())
        self.assertEqual(code, expected, payload)
        self.assertEqual(payload["ok"], expected == 0, payload)
        return payload["result"] if expected == 0 else payload["error"]

    def test_each_registered_si_edit_previews_graph_and_applies_only_exact_value_bytes(self):
        for address, case in CHANNEL_CASES.items():
            with self.subTest(address=address):
                raw = self.mdu.read_bytes()
                before = fingerprints(self.root)
                preview = self.cli("model", "field-set", self.mdu, address, case["after"], "--unit", case["unit"])
                graph = linked_graph(self.mdu)
                self.assertEqual(preview["input_sha256"], graph["input_sha256"])
                self.assertEqual(preview["files"], graph["files"])
                self.assertEqual(fingerprints(self.root), before)
                result = self.cli("model", "field-set", self.mdu, address, case["after"], "--unit", case["unit"],
                                  "--apply", "--expect-sha256", graph["input_sha256"])
                self.assertTrue(result["applied"])
                assert_exact_edit(raw, self.mdu.read_bytes(), address, case["after"])
                assert_unrelated_files(before, fingerprints(self.root), "model.mdu")
                self.mdu.write_bytes(raw)

    def test_inspection_unknown_duplicates_and_offsets_match_independent_byte_scanner(self):
        raw = b"\xef\xbb\xbf" + self.mdu.read_bytes() + b"[PHYSICS]\r\nUnifFrictCoef=0.04 # duplicate\r\n"
        self.mdu.write_bytes(raw)
        before = fingerprints(self.root)
        report = self.cli("model", "fields", self.mdu)
        rows = occurrences(raw)
        self.assertEqual(len(report["fields"]), len(rows))
        for actual, expected in zip(report["fields"], rows):
            self.assertEqual((actual["setting"], actual["line"], actual["occurrence"], actual["value"], actual["byte_start"], actual["byte_end"]),
                             (expected["address"], expected["line"], expected["occurrence"], expected["value"], expected["start"], expected["end"]))
        mystery = next(row for row in report["fields"] if row["setting"] == "unknown/mystery")
        self.assertEqual(mystery["registry_status"], "unindexed_unknown")
        self.assertIsNone(mystery["gui_console_owner"]["owner"])
        filtered = self.cli("model", "fields", self.mdu, "--section", "PHYSICS", "--key", "UNIFFRICTCOEF")
        self.assertEqual([row["occurrence"] for row in filtered["fields"]], [1, 2])
        error = self.cli("model", "field-set", self.mdu, "physics/uniffrictcoef", "0.041", "--unit", "s m-1/3", expected=3)
        self.assertEqual(error["code"], "ambiguous_setting")
        self.assertEqual(fingerprints(self.root), before)

    def test_wrong_units_scalars_ranges_and_unimplemented_keys_do_not_mutate_any_file(self):
        before = fingerprints(self.root)
        for address, value, unit, code in (
            ("geometry/waterlevini", "25", "cm", 4), ("physics/uniffrictcoef", "0.041", "m0.5 s-1", 4),
            ("time/dtmax", "0.25", "minutes", 4), ("physics/ag", "9.8", "m s-2", 3),
            ("geometry/waterlevini", "NaN", "m", 4), ("geometry/waterlevini", "1 # inject", "m", 4),
            ("geometry/waterlevini", "0\nKmx=2", "m", 4), ("geometry/waterlevini", "101", "m", 4),
            ("physics/uniffrictcoef", "0", "s m-1/3", 4), ("time/dtmax", "0.01", "s", 4)):
            with self.subTest(address=address, value=value):
                self.cli("model", "field-set", self.mdu, address, value, "--unit", unit, expected=code)
                self.assertEqual(fingerprints(self.root), before)

    def test_graph_hash_tracks_linked_bc_changes_and_rejects_mdu_only_hash(self):
        preview = self.cli("model", "field-set", self.mdu, "time/dtmax", "0.25", "--unit", "s")
        self.assertNotEqual(preview["input_sha256"], preview["before_sha256"])
        error = self.cli("model", "field-set", self.mdu, "time/dtmax", "0.25", "--unit", "s", "--apply",
                         "--expect-sha256", preview["before_sha256"], expected=4)
        self.assertEqual(error["code"], "stale_preview")
        bc = self.root / "boundaries.bc"
        bc.write_bytes(bc.read_bytes() + b"# changed linked input\n")
        before = fingerprints(self.root)
        error = self.cli("model", "field-set", self.mdu, "time/dtmax", "0.25", "--unit", "s", "--apply",
                         "--expect-sha256", preview["input_sha256"], expected=4)
        self.assertEqual(error["code"], "stale_preview")
        self.assertEqual(before, fingerprints(self.root))

    def test_apply_requires_graph_hash_and_ambiguous_friction_law_is_refused(self):
        before = fingerprints(self.root)
        error = self.cli("model", "field-set", self.mdu, "time/dtmax", "0.25", "--unit", "s", "--apply", expected=2)
        self.assertEqual(error["code"], "expected_hash_required")
        self.assertEqual(before, fingerprints(self.root))
        for replacement, code in ((b"UnifFrictType=0", 4), (b"UnifFrictType=1\r\nUnifFrictType=1", 3)):
            raw = self.mdu.read_bytes()
            self.mdu.write_bytes(raw.replace(b"UnifFrictType=1", replacement))
            before = fingerprints(self.root)
            self.cli("model", "field-set", self.mdu, "physics/uniffrictcoef", "0.041", "--unit", "s m-1/3", expected=code)
            self.assertEqual(before, fingerprints(self.root))
            self.mdu.write_bytes(raw)

    def test_missing_datum_refuses_without_changes(self):
        with nc.Dataset(self.root / "mesh_net.nc", "r+") as ds:
            ds.delncattr("vertical_datum")
            ds.variables["mesh2d_node_z"].delncattr("vertical_datum")
        before = fingerprints(self.root)
        self.cli("model", "field-set", self.mdu, "geometry/waterlevini", "0.25", "--unit", "m", expected=4)
        self.assertEqual(before, fingerprints(self.root))

    def test_spatial_initial_override_and_restart_refuse_without_changes(self):
        raw = self.mdu.read_bytes()
        for changed in (raw.replace(b"Kmx=0", b"Kmx=0\r\nWaterLevIniFile=override.xyz"),
                        raw.replace(b"RestartFile=", b"RestartFile=previous_rst.nc")):
            self.mdu.write_bytes(changed)
            before = fingerprints(self.root)
            self.cli("model", "field-set", self.mdu, "geometry/waterlevini", "0.25", "--unit", "m", expected=3)
            self.assertEqual(before, fingerprints(self.root))
        self.mdu.write_bytes(raw)

    def test_initial_level_must_exceed_every_bed_node_and_tunit_does_not_convert_dtmax(self):
        before = fingerprints(self.root)
        self.cli("model", "field-set", self.mdu, "geometry/waterlevini", "-3", "--unit", "m", expected=4)
        self.assertEqual(before, fingerprints(self.root))
        self.mdu.write_bytes(self.mdu.read_bytes().replace(b"TUnit=S", b"TUnit=M"))
        result = self.cli("model", "field-set", self.mdu, "time/dtmax", "0.25", "--unit", "s")
        self.assertEqual(result["after"], "0.25")
        report = self.cli("model", "fields", self.mdu, "--section", "time", "--key", "dtmax")
        self.assertEqual(report["fields"][0]["unit_evidence"]["unit"], "s")

    def test_unsupported_bed_modes_refuse_preview_and_direct_apply_despite_valid_node_bed(self):
        raw = self.mdu.read_bytes()
        # Keep a complete 2D projected mesh, valid positive-up node elevations,
        # datum and wet proposed elevation. Only the authoritative bed mode varies.
        with nc.Dataset(self.root / "mesh_net.nc") as ds:
            z = np.ma.asarray(ds["mesh2d_node_z"][:])
            self.assertEqual(z.size, 65)
            self.assertFalse(np.ma.getmaskarray(z).any())
            self.assertTrue(np.isfinite(z.data).all())
            self.assertTrue(np.all(z.data == -3.))
            self.assertEqual(ds["mesh2d_node_z"].units, "m")
            self.assertEqual(ds["mesh2d_node_z"].positive, "up")
        self.assertEqual(selected(raw, "geometry/kmx")["value"], "0")
        for mode in ("1", "2", "4", "5", "6"):
            changed = expected_edit(raw, "geometry/bedlevtype", mode)
            for address, case in CHANNEL_CASES.items():
                for apply in (False, True):
                    with self.subTest(mode=mode, address=address, apply=apply):
                        self.mdu.write_bytes(changed)
                        before = fingerprints(self.root)
                        args = ["model", "field-set", self.mdu, address, case["after"], "--unit", case["unit"]]
                        if apply:
                            args += ["--apply", "--expect-sha256", linked_graph(self.mdu)["input_sha256"]]
                        error = self.cli(*args, expected=3)
                        self.assertEqual(error["code"], "unsupported_field_bed_mode")
                        self.assertEqual(fingerprints(self.root), before)

    def test_missing_or_ambiguous_bed_mode_never_defaults_to_node_bed(self):
        raw = self.mdu.read_bytes()
        variants = ((raw.replace(b"BedlevType=3\r\n", b""), "unsupported_field_bed_mode"),
                    (raw.replace(b"BedlevType=3", b"BedlevType=3\r\nBedlevType=1"), "ambiguous_setting"),
                    (raw.replace(b"BedlevType=3", b"BedlevType=3\r\nBedlevType=3"), "ambiguous_setting"))
        for changed, expected_code in variants:
            for apply in (False, True):
                with self.subTest(expected_code=expected_code, apply=apply):
                    self.mdu.write_bytes(changed)
                    before = fingerprints(self.root)
                    args = ["model", "field-set", self.mdu, "geometry/waterlevini", "0.25", "--unit", "m"]
                    if apply:
                        args += ["--apply", "--expect-sha256", linked_graph(self.mdu)["input_sha256"]]
                    error = self.cli(*args, expected=3)
                    self.assertEqual(error["code"], expected_code)
                    self.assertEqual(fingerprints(self.root), before)

    def test_cell_bed_mode_with_filled_face_z_is_refused_even_when_all_node_z_are_valid(self):
        self.mdu.write_bytes(expected_edit(self.mdu.read_bytes(), "geometry/bedlevtype", "1"))
        with nc.Dataset(self.root / "mesh_net.nc", "r+") as ds:
            face = ds.createVariable("mesh2d_face_z", "f8", ("mesh2d_nFaces",), fill_value=-999.)
            face.setncatts({"units": "m", "positive": "up", "standard_name": "altitude", "mesh": "mesh2d", "location": "face"})
            face[:] = np.ma.masked_all(48)
        with nc.Dataset(self.root / "mesh_net.nc") as ds:
            self.assertTrue(np.ma.getmaskarray(ds["mesh2d_face_z"][:]).all())
            self.assertFalse(np.ma.getmaskarray(ds["mesh2d_node_z"][:]).any())
            self.assertTrue(np.all(ds["mesh2d_node_z"][:] == -3.))
        for apply in (False, True):
            with self.subTest(apply=apply):
                before = fingerprints(self.root)
                args = ["model", "field-set", self.mdu, "geometry/waterlevini", "0.25", "--unit", "m"]
                if apply:
                    args += ["--apply", "--expect-sha256", linked_graph(self.mdu)["input_sha256"]]
                error = self.cli(*args, expected=3)
                self.assertEqual(error["code"], "unsupported_field_bed_mode")
                self.assertEqual(fingerprints(self.root), before)

    def test_explicit_unsupported_or_duplicate_conveyance_is_refused_with_node_bed_mode_three(self):
        raw = self.mdu.read_bytes()
        for mode, expected_code in (("-1", "unsupported_field_bed_mode"), ("0", "unsupported_field_bed_mode"),
                                    ("2", "unsupported_field_bed_mode"), ("3", "unsupported_field_bed_mode"),
                                    ("1\r\nConveyance2D=1", "ambiguous_setting")):
            changed = raw.replace(b"BedlevType=3\r\n", b"BedlevType=3\r\nConveyance2D=" + mode.encode("ascii") + b"\r\n")
            for apply in (False, True):
                with self.subTest(mode=mode, apply=apply):
                    self.mdu.write_bytes(changed)
                    before = fingerprints(self.root)
                    args = ["model", "field-set", self.mdu, "geometry/waterlevini", "0.25", "--unit", "m"]
                    if apply:
                        args += ["--apply", "--expect-sha256", linked_graph(self.mdu)["input_sha256"]]
                    error = self.cli(*args, expected=3)
                    self.assertEqual(error["code"], expected_code)
                    self.assertEqual(fingerprints(self.root), before)

    def test_undeclared_conveyance_stays_distinct_from_explicit_supported_mode(self):
        raw = self.mdu.read_bytes()
        before = fingerprints(self.root)
        undeclared = self.cli("model", "field-set", self.mdu, "geometry/waterlevini", "0.25", "--unit", "m")
        self.assertEqual(undeclared["bed_mode"]["bedlevtype"], 3)
        self.assertEqual(undeclared["bed_mode"]["conveyance2d"], "undeclared_as_in_M3_fixture")
        self.assertEqual(fingerprints(self.root), before)
        self.mdu.write_bytes(raw.replace(b"BedlevType=3\r\n", b"BedlevType=3\r\nConveyance2D=1\r\n"))
        before = fingerprints(self.root)
        explicit = self.cli("model", "field-set", self.mdu, "geometry/waterlevini", "0.25", "--unit", "m")
        self.assertEqual(explicit["bed_mode"]["conveyance2d"], 1)
        self.assertEqual(fingerprints(self.root), before)

    def test_console_owner_evidence_does_not_infer_unknown_gui_property(self):
        raw = self.mdu.read_bytes()
        report = self.cli("model", "fields", self.mdu)
        water = next(row for row in report["fields"] if row["setting"] == "geometry/waterlevini")
        self.assertEqual(water["gui_console_owner"]["status"], "unknown")
        history = next(row for row in report["fields"] if row["setting"] == "output/hisinterval")
        self.assertEqual(history["gui_console_owner"]["owner"], "HisOutputDeltaT")
        self.assertIn("raw HisInterval", history["gui_console_owner"]["qualification"])
        self.assertEqual(raw, self.mdu.read_bytes())

    def test_verified_case_provenance_does_not_validate_current_preview_or_apply(self):
        raw = self.mdu.read_bytes()
        registry = Path(__file__).resolve().parents[1] / "src/dfm_cli/fields_registry.json"
        registry_hash = hashlib.sha256(registry.read_bytes()).hexdigest()
        inspection = self.cli("model", "fields", self.mdu)
        for address, case in CHANNEL_CASES.items():
            with self.subTest(address=address):
                self.mdu.write_bytes(raw)
                inspected = next(row for row in inspection["fields"] if row["setting"] == address)
                before = fingerprints(self.root)
                args = ["model", "field-set", self.mdu, address, case["after"], "--unit", case["unit"]]
                preview = self.cli(*args)
                self.assertEqual(fingerprints(self.root), before)
                applied = self.cli(*args, "--apply", "--expect-sha256", linked_graph(self.mdu)["input_sha256"])
                for evidence in (inspected, preview["evidence"], applied["evidence"]):
                    known = evidence["known_verified_case"]
                    self.assertEqual(known["state"], "verified_case")
                    self.assertEqual(known["registry_sha256"], registry_hash)
                    self.assertRegex(known["verification_sha256"], r"^[0-9a-f]{64}$")
                    self.assertEqual(evidence["native_validation"], "not_performed_for_this_invocation")
                    self.assertEqual(evidence["engine_behavior_from_static_index"], "unknown")
                    self.assertEqual(evidence["gui_console_owner"]["status"], "unknown")
                for result in (preview, applied):
                    self.assertEqual(result["checks"]["native_field_isolation"], "not_performed")
                    self.assertEqual(result["checks"]["scientific_validation"], "not_performed")
                assert_exact_edit(raw, self.mdu.read_bytes(), address, case["after"])
                assert_unrelated_files(before, fingerprints(self.root), "model.mdu")
        history = next(row for row in inspection["fields"] if row["setting"] == "output/hisinterval")
        self.assertNotIn("known_verified_case", history)


